package br.com.fiap.bank.core.presentation;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import jakarta.validation.Valid; import java.util.*; import br.com.fiap.bank.core.application.BankService; import br.com.fiap.bank.core.application.dto.*; @RestController @RequestMapping("/api/v1/clientes") public class ClienteController { private final BankService service; public ClienteController(BankService s){service=s;} @GetMapping public List<ClienteResponse> all(){return service.clientes();} @GetMapping("/{id}") public ClienteResponse get(@PathVariable Long id){return service.cliente(id);} @GetMapping("/cpf/{cpf}") public ClienteResponse cpf(@PathVariable String cpf){return service.clienteCpf(cpf);} @PostMapping public ResponseEntity<ClienteResponse> create(@Valid @RequestBody CriarClienteRequest r){return ResponseEntity.status(201).body(service.criar(r));} @PutMapping("/{id}") public ClienteResponse update(@PathVariable Long id,@Valid @RequestBody CriarClienteRequest r){return service.atualizar(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.excluir(id);} }
